import {parseCSV,coerce,summarize,run,DEFAULT_CONFIG,createPlan,updatePlan,isPlanStale,recordRun,serializeWorkspace,restoreWorkspace,validateActivity,activityContext,SCORE_LABELS} from './engine.mjs';
const $=s=>document.querySelector(s),esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=(v,d=1)=>(v*100).toFixed(d)+'%',fmt=v=>Number(v).toLocaleString('en-CA'),pp=v=>(v>0?'+':'')+v.toFixed(2)+' pp';
const names={users:'用户',campaigns:'活动',contents:'内容',experiments:'历史实验'};
const categories={heritage_experience:'非遗 / 文博体验',academic_deep_dive:'学术 / 深度分享',interest_social:'兴趣社群 / 社交',career_cultural_exchange:'职业 / 文化交流',experimental:'试验型活动'};
let data,schema,summary,result=null,view='overview',stage=0,table='experiments',page=0,query='',stale=false;
let config={...DEFAULT_CONFIG};
let plans=[],activeId=null,storageAvailable=true;
const STORAGE_KEY='growth-copilot-workspace-v2';
const currentPlan=()=>plans.find(p=>p.activity.id===activeId);
const replacePlan=p=>{plans=plans.map(x=>x.activity.id===p.activity.id?p:x);};
function persistWorkspace(){try{localStorage.setItem(STORAGE_KEY,serializeWorkspace(plans,activeId));storageAvailable=true;return true;}catch{storageAvailable=false;return false;}}
function syncPlan(){const p=currentPlan();config={...p.config};result=p.lastRun?run(data,p.lastRun.config,p.lastRun.activity):null;stale=isPlanStale(p);}
function initializeWorkspace(){
 try{const raw=localStorage.getItem(STORAGE_KEY);if(raw){const s=restoreWorkspace(raw);plans=s.plans;activeId=s.activeId;}}catch{storageAvailable=false;}
 if(!plans.length){const p=createPlan({id:'example-community-plan',name:'社区增长计划 · 示例',category:'heritage_experience',date:null,audience:'对传统文化感兴趣的社区新用户',expectedNewUsers:null});plans=[p];activeId=p.activity.id;}
 syncPlan();
}
const main=$('#main');
async function get(path,type='json'){const r=await fetch(path);if(!r.ok)throw new Error(`无法读取 ${path} (${r.status})`);return r[type]();}
function toast(s){const el=$('#toast');el.textContent=s;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2500);}
function download(name,body,type){const u=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),5000);}
function modal(html){$('#detail-body').innerHTML=html;$('#detail').showModal();}
function header(title,sub,eyebrow,actions=''){return`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div><div class="head-actions">${actions}</div></div>`;}
function render(){document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.view===view));$('#breadcrumb').textContent={overview:'活动工作台',evidence:'历史数据',guide:'方法与边界'}[view];if(view==='overview')overview();else if(view==='evidence')evidence();else guide();}
function overview(){
 const p=currentPlan(),a=p.activity,ctx=activityContext(data,a),ref=ctx.historicalReference;
 main.innerHTML=header('下一轮增长，先验证什么？','围绕活动或整个社区，比较下一批值得验证的增长实验。','ACTIVITY WORKSPACE',`<span class="pill neutral">V4 · 决策看板</span>`)+
 `<div class="activity-toolbar" aria-label="活动操作栏"><label class="activity-switch"><span>当前活动</span><select id="activity-select" aria-label="切换活动">${plans.map(x=>`<option value="${esc(x.activity.id)}" ${x.activity.id===activeId?'selected':''}>${esc(x.activity.name)}</option>`).join('')}</select></label><button class="button secondary" id="new-activity">＋ 新建活动</button><div class="toolbar-actions"><button class="button secondary" id="edit-activity">编辑活动</button><button class="button secondary" id="edit-conditions">调整条件</button><button class="button secondary" id="save-plan">保存方案</button><button class="button secondary" id="export-top" ${!result?'disabled':''}>导出方案</button><button class="button" id="run-top">${result?'重新生成':'生成建议'} ↗</button></div></div>
 <div class="save-status" role="status"><span>${storageAvailable?'仅保存在此浏览器 · 不会写入历史数据':'浏览器存储不可用或保存数据无法读取 · 请导出备份'}</span><span>${stale?'● 已修改，结果待更新':p.savedAt?'已保存 '+new Date(p.savedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):result?'建议已生成，可保存方案':'活动草稿 · 尚未生成建议'}</span></div>
 <details class="input-summary" ${!result?'open':''}><summary>本轮输入：${esc(a.name)} · ${fmt(config.budget)} CAD · ${config.team} 人 · 查看或编辑顶部条件</summary><section class="activity-brief panel" aria-label="当前活动信息"><div class="activity-description"><div class="eyebrow">YOUR NEXT EVENT</div><h2>${esc(a.name)}</h2><div class="event-meta"><span>${a.scope==='community'?'社区整体增长':categories[a.category]}</span><span>◷ ${a.date||'日期待定'}</span><span>预计首次参与 ${a.expectedNewUsers===null?'待定':fmt(a.expectedNewUsers)+' 人'}</span></div><p>目标人群：${esc(a.audience)}</p><p class="brief-note">只填写计划信息。当前Demo不包含活动执行后的结果回填。</p></div><div class="brief-constraints"><div class="eyebrow">EXPERIMENT CONDITIONS</div><div><strong>${fmt(config.budget)} <small>CAD</small></strong><span>增长实验预算</span></div><div class="constraint-chips"><span>${config.team} 人核心团队</span><span>最多 ${config.parallel} 个实验</span><span>${config.hours===null?'人时待核实':config.hours+' 人时'}</span><span>4 周 / 14 天观察</span></div><p>可入组新用户：${config.futureUsers===null?'待核实':fmt(config.futureUsers)+' 人'} · 需符合触达同意</p></div></section>
 </details><section class="planning-steps" aria-label="使用步骤"><span class="complete">1 <b>创建活动</b></span><i>→</i><span class="${result?'complete':''}">2 <b>生成与调整建议</b></span><i>→</i><span class="${p.savedAt&&!stale?'complete':''}">3 <b>保存方案</b></span></section>
 <div id="decision-dashboard">${result?dashboardHTML():''}</div><div class="workspace activity-workspace"><div><details class="panel agent-details" ${!result?'open':''}><summary>查看流程与判断依据 <small>View Agent Reasoning · 六步流程</small></summary><section><div class="panel-head"><h2>本轮增长，适合实验什么？</h2><button class="text-button" id="export" ${!result?'disabled':''}>导出方案 ↓</button></div><div class="pipeline">${['候选生成','去重与多样性','证据审查','初次排序','方案改进','重新排序'].map((s,i)=>`${i?'<span class="chevron">›</span>':''}<button class="stage ${stage===i?'active':''}" data-stage="${i}" aria-pressed="${stage===i}"><span class="num">${i+1}</span><span><strong>${s}</strong><small>${['GENERATION','DIVERSITY','REFLECTION','RANKING','EVOLUTION','RE-RANKING'][i]}</small></span></button>`).join('')}</div><div id="result-panel"></div></section></details></div>
 <aside class="activity-reference"><section class="panel"><div class="panel-head"><h2>${a.scope==='community'?'全社区历史参考':'同类型历史参考'}</h2><span class="pill neutral">${ref.count} 场</span></div><div class="panel-body"><div class="reference-rate">${ref.repeatRate===null?'—':pct(ref.repeatRate)}</div><p class="reference-title">${a.scope==='community'?'全部活动':categories[a.category]} · 14天二次参与率</p><p class="stage-description">${ref.repeatNewUsers} / ${ref.eligibleNewUsers} 名当时的新用户。只作历史参照，不是这场新活动的预计结果。</p><button class="text-button" id="chart-evidence">查看这 ${ref.count} 场历史活动 ↗</button></div></section><section class="panel reference-context"><div class="panel-head"><h2>业务背景</h2></div><div class="panel-body"><div class="baseline-pair"><span>历史基线 <b>18%</b></span><i>→</i><span>重构后 <b>31%</b></span></div><p class="stage-description">相对变化 +72.2%，来自不同时间的用户观察，不是已证明的因果效果。</p><p class="reference-note">历史快照中的 New 280 人已完成14天窗口。本活动需要新的首次参与用户。</p></div></section></aside></div>`;
 renderResult();
 document.querySelectorAll('[data-reasoning]').forEach(b=>b.onclick=()=>{document.querySelector('.agent-details').open=true;stage=+b.dataset.reasoning;document.querySelector(`[data-stage="${stage}"]`).click();document.querySelector('.agent-details').scrollIntoView({behavior:'smooth',block:'start'});});
 $('#export-top').onclick=exportResult;$('#run-top').onclick=execute;$('#export').onclick=exportResult;
 $('#new-activity').onclick=()=>openEditor('new');$('#edit-activity').onclick=()=>openEditor('activity');$('#edit-conditions').onclick=()=>openEditor('conditions');$('#save-plan').onclick=saveCurrentPlan;
 $('#activity-select').onchange=e=>{activeId=e.target.value;syncPlan();stage=result?5:0;persistWorkspace();render();};
 document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{stage=+b.dataset.stage;document.querySelectorAll('[data-stage]').forEach(n=>{n.classList.toggle('active',+n.dataset.stage===stage);n.setAttribute('aria-pressed',+n.dataset.stage===stage);});renderResult();});
 $('#chart-evidence').onclick=()=>{table='campaigns';view='evidence';page=0;query=a.scope==='community'?'':a.category;render();window.scrollTo({top:0});};
}
function saveCurrentPlan(){
 const p=currentPlan();if(!result){toast('请先生成建议，再保存方案。活动草稿已保留。');return;}
 if(stale){toast('活动或条件已变化，请先重新生成建议。');return;}
 const previous=p.savedAt;p.savedAt=new Date().toISOString();
 if(persistWorkspace()){overview();toast('方案已保存到此浏览器；可切换活动或导出备份。');}
 else{p.savedAt=previous;overview();toast('未能写入浏览器存储，请用“导出方案”备份。');}
}
function openEditor(mode){
 if(mode==='new'&&plans.length>=100){toast('最多保存100个活动，请先导出已有方案。');return;}
 const p=currentPlan(),isNew=mode==='new';
 const a=isNew?{id:crypto.randomUUID(),name:'',category:'heritage_experience',date:null,audience:'首次参加社区活动的新用户',expectedNewUsers:null}:{...p.activity};
 const c=isNew?{...p.config,futureUsers:null}:{...p.config};
 const drawer=$('#editor');
 $('#editor-title').textContent={new:'创建一场新活动',activity:'编辑活动信息',conditions:'调整实验条件'}[mode];
 $('#editor-description').textContent=isNew?'填写计划信息即可。实验资源沿用当前设置，可以随时调整。':mode==='activity'?'修改后会保留旧建议，并提示你重新生成。':'这里设置的是增长实验资源，不是整场活动的总成本。';
 $('#editor-fields').innerHTML=mode!=='conditions'?`
 <label class="field"><span>任务范围</span><select id="task-scope"><option value="activity" ${a.scope!=='community'?'selected':''}>单场活动</option><option value="community" ${a.scope==='community'?'selected':''}>社区整体增长</option></select></label>
 <label class="field"><span>活动 / 任务名称 <em>必填</em></span><input id="event-name" maxlength="80" required placeholder="例如：周末非遗拓印体验" value="${esc(a.name)}"></label>
 <label class="field"><span>活动类型</span><select id="event-category">${Object.entries(categories).map(([k,v])=>`<option value="${k}" ${a.category===k?'selected':''}>${v}</option>`).join('')}</select></label>
 <label class="field"><span>计划日期 <em>尚未确定可留空</em></span><input id="event-date" type="date" value="${a.date||''}"></label>
 <label class="field"><span>目标人群 <em>必填</em></span><textarea id="event-audience" maxlength="160" rows="3" required>${esc(a.audience)}</textarea></label>
 <label class="field"><span>预计首次参与人数 <em>不是报名总人数</em></span><input id="event-new-users" type="number" min="0" max="1000000" step="1" placeholder="未知可留空" value="${a.expectedNewUsers??''}"></label>
 <div class="editor-note">本版目标是提高首次参与后14天内的再次到场。实际到场率、复参与率无需提前填写。</div>
 ${isNew?`<div class="inherit-summary"><b>沿用实验条件</b><p>预算 ${fmt(c.budget)} CAD · 核心团队 ${c.team} 人 · 最多 ${c.parallel} 个实验</p><p>新活动的可入组人数重新留空，需按实际同意情况核实。</p></div>`:''}`:`
 <fieldset class="existing-actions"><legend>当前已经实施的策略（避免重复推荐）</legend>${data.experiments.map(e=>`<label><input type="checkbox" name="existing" value="${e.experiment_id}" ${(c.existingActions||[]).includes(e.experiment_id)?'checked':''}> ${esc(e.experiment_name)}</label>`).join('')}</fieldset>
 <label class="field"><span>增长实验现金预算 <em>CAD</em></span><input id="budget" type="number" min="0" max="100000" step="1" required value="${c.budget}"></label>
 <label class="field"><span>本轮排序偏好</span><select id="preference"><option value="balanced" ${c.preference==='balanced'?'selected':''}>综合判断优先</option><option value="evidence" ${c.preference==='evidence'?'selected':''}>随机试验证据优先</option><option value="cost" ${c.preference==='cost'?'selected':''}>现金投入较低优先</option></select></label>
 <div class="field-row"><label class="field"><span>核心执行人数</span><input id="team" type="number" min="1" max="20" step="1" required value="${c.team}"></label><label class="field"><span>本轮最多实验</span><select id="parallel">${[1,2,3].map(n=>`<option value="${n}" ${n===c.parallel?'selected':''}>${n} 个</option>`).join('')}</select></label></div>
 <label class="field"><span>可用总人时 <em>未知可留空</em></span><input id="hours" type="number" min="0" step="1" placeholder="待核实" value="${c.hours??''}"></label>
 <label class="field"><span>可入组新用户 <em>已满足同意要求</em></span><input id="futureUsers" type="number" min="0" ${a.expectedNewUsers!==null?`max="${a.expectedNewUsers}"`:''} step="1" placeholder="待核实" value="${c.futureUsers??''}"></label>
 <div class="editor-note">${a.expectedNewUsers===null?'预计首次参与人数尚未确定。':`本活动预计首次参与 ${a.expectedNewUsers} 人。`} 可入组人数不能超过首次参与人数；留空不会被当作0或已通过。</div>
 <div class="locked"><span>组织总人数</span>20 人</div><div class="locked"><span>实施周期 / 观察窗</span>4 周 / 14 天</div><div class="locked"><span>工程 / 隐私</span>Low / Conservative</div>`;
 $('#editor-submit').textContent=isNew?'创建活动':mode==='activity'?'保存活动信息':'应用实验条件';
 $('#editor-error').textContent='';
 $('#editor-form').onsubmit=e=>{
  e.preventDefault();if(!$('#editor-form').reportValidity())return;
  const number=id=>$('#'+id).value===''?null:Number($('#'+id).value);
  try{
   if(mode==='conditions'){Object.assign(c,{existingActions:[...document.querySelectorAll('input[name=existing]:checked')].map(e=>e.value),budget:number('budget'),team:number('team'),parallel:number('parallel'),hours:number('hours'),futureUsers:number('futureUsers'),preference:$('#preference').value});}
   else Object.assign(a,{scope:$('#task-scope').value,name:$('#event-name').value.trim(),category:$('#event-category').value,date:$('#event-date').value||null,audience:$('#event-audience').value.trim(),expectedNewUsers:number('event-new-users')});
   validateActivity(a,c);
   if(isNew){plans.push(createPlan(a,c));activeId=a.id;}else replacePlan(updatePlan(p,a,c));
   const saved=persistWorkspace();syncPlan();if(isNew)stage=0;drawer.close();overview();
   toast(saved?(isNew?'活动已创建。确认实验条件后，点击“生成建议”。':stale?'已更新，点击“重新生成”刷新建议。':'已更新活动设置。'):'设置已更新，但浏览器存储不可用，请导出备份。');
  }catch(err){$('#editor-error').textContent=err.message;}
 };
 drawer.showModal();
}
function execute(){
 try{const p=currentPlan();result=run(data,p.config,p.activity);replacePlan(recordRun(p));config={...p.config};stale=false;stage=5;persistWorkspace();overview();toast(`已为“${p.activity.name}”生成 ${result.ranking.selected.length} 个条件性推荐。`);}
 catch(e){toast(e.message);}
}

function renderResult(){const el=$('#result-panel');if(!result){el.innerHTML=`<div class="empty"><div class="empty-icon">✳</div><h3>活动已就位，下一步是实验设计</h3><p>核对顶部的活动信息与实验条件，点击“生成建议”。系统将参考同类型历史活动，审查8个历史实验的证据。</p><button class="button" id="empty-generate">为这场活动生成建议 →</button><div class="mini-data"><span>800 位用户</span><span>24 场历史活动</span><span>8 个历史实验</span></div></div>`;$('#empty-generate').onclick=execute;return;}
 const contextLine=result.activity?`<div class="result-context">方案对象：${esc(result.activity.name)} · ${result.activity.scope==='community'?'社区整体增长':categories[result.activity.category]}${result.context.repeatWindowEnd?' · 14天观察截止 '+result.context.repeatWindowEnd:' · 日期待定'}</div>`:'';
 const staleNote=(stale?'<div class="stale">活动或条件已修改。下方保留旧方案，请点击顶部“重新生成”。</div>':'')+contextLine;
 if(stage===0)el.innerHTML=staleNote+`<div class="panel-body"><p class="stage-description">从8个历史案例形成候选。机制是待验证假设，未来增量保持未知。</p>${result.generated.map((c,i)=>`<article class="candidate"><div class="candidate-top"><span class="candidate-index">${String(i+1).padStart(2,'0')}</span><h3>${c.name}</h3><span class="pill neutral">待验证假设</span></div><p>${c.hypothesis}</p><div class="candidate-meta"><span>历史现金 <strong>${fmt(c.cost)}</strong> CAD</span><span><strong>${c.hours}</strong> 人时</span><span>来源 ${c.sourceId}</span><button class="text-button" data-candidate="${c.id}">查看方案 ↗</button></div></article>`).join('')}</div>`;
 else if(stage===2)el.innerHTML=staleNote+`<div class="panel-body"><p class="stage-description">检查设计、样本、迁移与硬约束。以下问题来自字段规则，未调用外部模型。</p>${result.reviewed.map(c=>`<article class="review-box"><div class="review-head"><h3>${c.name}</h3><span class="pill ${c.status==='revise'?'block':'warn'}">${c.status==='revise'?'需修订':'有条件保留'}</span></div><p>${c.sourceId} · 历史观察差异 ${pp(c.experiment.observed_diff_pp)} · ${c.experiment.study_design==='randomized_pilot'?'随机试点':'观察比较'}</p>${c.issues.slice(0,2).map(issueHTML).join('')}<details><summary>查看全部 ${c.issues.length} 项审查与证据</summary>${c.issues.slice(2).map(issueHTML).join('')}<button class="text-button" data-candidate="${c.id}">打开原始证据 ↗</button></details></article>`).join('')}</div>`;
 else if(stage===1){const d=result.diversity;el.innerHTML=staleNote+`<div class="panel-body"><h3>保留 ${d.kept.length} 个候选，移除 ${d.removed.length} 个重复项</h3><p>${esc(d.method)}</p>${Object.entries(d.groups).map(([k,ids])=>`<article class="candidate"><h3>${esc(k)}</h3><p>${ids.map(id=>esc(result.generated.find(c=>c.id===id).name)).join(' · ')}</p></article>`).join('')}${d.warnings.map(x=>`<p class="notice">${esc(x)}</p>`).join('')}<p>当前目标是二次参与；多样性体现在实现这一目标的不同机制，不强行加入无关获客或变现方案。</p></div>`;}
 else if(stage===4){el.innerHTML=staleNote+`<div class="panel-body"><p>针对初排前三个候选改进执行和验证设计。原始数据、成本、风险标签不因文字修改而改变。</p>${result.evolved.map(c=>`<article class="candidate"><h3>${esc(c.name)} · V1 → V2</h3><p><b>原方案：</b>${esc(c.changes[0].before)}</p><p><b>改进：</b>${esc(c.changes[0].after)}</p><p><b>回应审查：</b>${esc(c.changes[0].addresses.join('、'))}</p><details><summary>执行计划与成功指标</summary>${Object.entries(c.validationPlan).map(([k,v])=>`<p>${esc(v)}</p>`).join('')}</details><p class="chart-caption">${esc(c.evidenceChange)}</p></article>`).join('')}</div>`;}
 else {const r=stage===3?result.initialRanking:result.ranking,t=r.totals;el.innerHTML=staleNote+`<div class="panel-body"><p class="stage-description">${esc(r.method)}评分是演示判断，不是预计留存率。风险分越高表示风险越可控。</p><div class="recommendation"><h3>${r.selected.length?r.selected.map(c=>esc(c.name)).join(' ＋ '):'当前约束下无可选组合'}</h3><p>条件性推荐 · ${t.cost} CAD 历史现金占位 · ${t.hours} 人时 · 峰值 ${t.staff} 人</p></div><div class="table-wrap"><table><thead><tr><th>候选</th><th>总分 / 10</th><th>组合判断</th></tr></thead><tbody>${r.ordered.map(c=>`<tr><td>${esc(c.name)}${c.version?' · V2':''}<details><summary>六维评分与依据</summary>${Object.entries(c.scores).map(([k,v])=>`<p><b>${SCORE_LABELS[k]} ${v.toFixed(1)} / 权重 ${Math.round(r.weights[k]*100)}%</b><br>${esc(c.scoreReasons[k])}</p>`).join('')}</details></td><td>${c.totalScore.toFixed(2)}</td><td>${esc(r.decisions.find(d=>d.candidateId===c.id).reason)}<br><button class="text-button" data-candidate="${c.parentId||c.id}">证据 ↗</button></td></tr>`).join('')}</tbody></table></div><details><summary>两两比较 · ${r.comparisons.length} 组</summary>${r.comparisons.map(x=>`<p>${esc(x.a)} vs ${esc(x.b)}：${x.winner?esc(x.winner)+' 领先':'并列'}，分差 ${Math.abs(x.margin).toFixed(2)}</p>`).join('')}<p>这是同一评分体系的两两比较，不是多个模型的独立投票。</p></details>${stage===5?gateHTML():''}<div class="unknown"><strong>执行前待核实</strong><ul>${r.unknown.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></div>`;}
 el.querySelectorAll('[data-candidate]').forEach(b=>b.onclick=()=>candidateDetail(b.dataset.candidate));
}
function dashboardHTML(){
 const r=result.ranking,m=result.metaReview,g=result.qualityGate;
 const confidence=c=>c.scores.evidence>=8?'中高':c.scores.evidence>=6?'中':'低';
 const card=(c,i)=>{const e=c.experiment;return `<article class="experiment-card"><div class="candidate-top"><span class="candidate-index">${i+1}</span><h3>${esc(c.name)}</h3></div><div class="card-badges"><span class="pill warn">条件性推荐</span><span>优先分 ${c.totalScore.toFixed(2)} / 10</span><span>证据信心：${confidence(c)}</span></div><p class="card-next"><b>建议行动</b><br>${esc(c.action)}</p><dl><dt>目标人群</dt><dd>${esc(c.target)}</dd><dt>为什么选它</dt><dd>在当前权重下得分 ${c.totalScore.toFixed(2)}，加入组合后未超出已知预算、人力与数量限制。未知条件仍需核实。</dd><dt>支持证据</dt><dd>${esc(c.sourceId)}：处理组 ${e.treatment_repeat_14d}/${e.treatment_n}，比较组 ${e.comparison_repeat_14d}/${e.comparison_n}；观察差异 ${pp(e.observed_diff_pp)}。${e.study_design==='randomized_pilot'?'历史随机试点':'观察比较，存在偏差'}，不是未来效果预测。</dd><dt>成功指标</dt><dd>首次实际参与后14天再次实际参与；目标差异与样本量需执行前确定。</dd><dt>成本与风险</dt><dd>${c.cost} CAD、${c.hours} 人时（历史占位）；${esc(c.issues.filter(x=>x.severity!=='note').map(x=>x.title).join('、')||'仍需核实同意与执行条件')}。</dd></dl><details><summary>假设与验证计划</summary><p>${esc(c.hypothesis)}</p><p>${esc(c.design)}</p><p>第1周准备，第2周入组，第3–4周完成14天观察；各实验用户池互斥。记录退订、投诉及实际成本，提前约定停止阈值。</p><p>信心标签仅根据演示证据分划分，不代表统计成功概率。</p></details><button class="text-button" data-reasoning="4">查看方案改进与完整判断 ↗</button></article>`;};
 return `${stale?'<div class="stale">输入已修改：以下是上次方案，请先点击“重新生成”。</div>':''}<section class="decision-summary panel"><div class="eyebrow">DECISION SUMMARY</div><h2>本轮优先做什么</h2><p class="summary-recommendations">${r.selected.length?'优先验证：'+r.selected.map(c=>esc(c.name)).join(' ＋ '):'当前条件下暂不建议启动实验'}</p><p>${r.selected.length?'这些方案围绕新用户二次参与，在当前评分与已知资源限制下优先进入验证。':'目前没有满足条件的组合，请先查看限制原因，调整资源或修订方案。'}</p>${r.selected.length?`<p><b>资源参考：</b>CAD ${fmt(r.totals.cost)} · ${r.totals.hours} 人时 · 并行峰值 ${r.totals.staff} 人 <span class="chart-caption">（历史占位，需核实正式报价）</span></p><p><b>执行前先确认：</b>${r.selected.some(c=>c.sourceId==='EXP001')?'相关推荐是否已在现有流程中；':''}可入组人数、样本量及体验护栏。</p><a class="button secondary" href="#recommended-experiments">查看 ${r.selected.length} 个实验的具体方案 ↓</a>`:'<button class="button secondary" data-reasoning="5">查看限制与未入选原因 ↓</button>'}<p class="chart-caption">${g.status==='needs_review'?'质量复核仍有待解决问题':'决策草案有条件通过'} · 非执行批准 · 不强行凑满3个</p></section><div class="dashboard-heading" id="recommended-experiments" tabindex="-1"><h2>推荐增长实验</h2><span>Recommended Growth Experiments · ${r.selected.length} / 最多 ${result.config.parallel}</span></div><div class="experiment-grid">${r.selected.map(card).join('')||'<div class="notice">当前没有可推荐实验。下方综合复核会解释阻断原因。</div>'}</div><section class="panel dashboard-scores"><div class="panel-head"><h2>六维取舍，一眼比较</h2><span>分数越高越有利 · /10</span></div><div class="table-wrap"><table><thead><tr><th>实验</th>${Object.values(SCORE_LABELS).map(k=>`<th>${k}</th>`).join('')}</tr></thead><tbody>${r.selected.map(c=>`<tr><td>${esc(c.name)}</td>${Object.values(c.scores).map(n=>`<td>${n.toFixed(1)}</td>`).join('')}</tr>`).join('')||'<tr><td colspan="7">暂无推荐；可在完整流程中查看全部候选评分。</td></tr>'}</tbody></table></div><button class="text-button" data-reasoning="5">比较全部候选、两两分差与质量检查 ↗</button></section><section class="panel meta-review"><div class="eyebrow">META-REVIEW · 本轮综合复核</div><h2>这次决策揭示了什么？</h2><p>综合已有结果，不新增方案、不重新排序、不覆盖硬性限制。这里是本轮总结，不代表系统获得了新实验结果。</p><div class="summary-grid">${[['跨方案洞察',m.cross_hypothesis_insights],['共同风险与约束',m.shared_risks],['关键证据缺口',m.critical_evidence_gaps]].map(([title,items])=>`<div><h3>${title}</h3><ul>${items.map(x=>`<li>${esc(x)}</li>`).join('')||'<li>没有重复出现的规则风险；单项风险见方案卡片。</li>'}</ul></div>`).join('')}</div><details open><summary>为什么优先这些方案，而不是其他方案？</summary><p>${esc(m.final_decision_rationale)}</p></details></section>`;
}
function gateHTML(){const g=result.qualityGate,it=result.iteration;return `<section class="quality-card"><div class="eyebrow">QUALITY GATE</div><h3>${g.status==='needs_review'?'仍有待复核问题':'草案有条件通过'}</h3><p>决策草案质量与执行就绪分开判断。当前未达到直接上线条件。</p>${g.issues.map(i=>`<p>• ${esc(i.message)}</p>`).join('')}<h3>有限迭代 · ${it.rounds.length} / ${it.maxRounds} 轮</h3>${it.rounds.map(r=>`<p>${esc(r.outcome)}</p>${r.tasks.map(t=>`<p><b>${esc(t.stage)}</b>：${esc(t.reason)} → ${esc(t.action)}</p>`).join('')}<details><summary>偏好敏感性比较</summary>${r.alternatives.map(a=>`<p>${a.preference==='cost'?'成本优先':'证据优先'}：${a.selected.join('、')||'无可行组合'}</p>`).join('')}</details>`).join('')||'<p>未触发额外复核。</p>'}<details><summary>改进前后评分</summary>${result.versionComparison.map(c=>`<p>${c.original} → ${c.variant}：${c.originalScore.toFixed(2)} → ${c.variantScore.toFixed(2)}。${esc(c.reason)}</p>`).join('')}</details></section>`;}
function issueHTML(i){return`<div class="issue"><span class="pill ${i.severity==='block'?'block':i.severity==='warning'?'warn':'neutral'}">${{block:'约束',warning:'注意',note:'边界'}[i.severity]}</span> <b>${i.title}</b><p>${i.detail}</p></div>`;}
function candidateDetail(id){const c=result.reviewed.find(x=>x.id===id),e=c.experiment;modal(`<div class="eyebrow">${c.sourceId} / EVIDENCE TRACE</div><h2>${c.name}</h2><div class="detail-grid"><div class="detail-stat"><b>${pct(e.treatment_repeat_14d/e.treatment_n)}</b>处理组 ${e.treatment_repeat_14d} / ${e.treatment_n}</div><div class="detail-stat"><b>${pct(e.comparison_repeat_14d/e.comparison_n)}</b>比较组 ${e.comparison_repeat_14d} / ${e.comparison_n}</div></div><p>观察差异 ${pp(e.observed_diff_pp)}；描述性95%区间 [${e.descriptive_diff_ci95_low_pp.toFixed(2)}, ${e.descriptive_diff_ci95_high_pp.toFixed(2)}] pp。不能将该区间视为已消除偏差或已确认因果。</p><h3>要验证的假设</h3><p>${c.hypothesis}</p><h3>干预与比较</h3><p>${c.action}</p><p>${c.design}</p><h3>主指标与人群</h3><p>${c.metric}。${esc(c.target)}。</p><h3>历史限制</h3><p>${e.limitations}</p><table><tbody>${[['工程投入',e.engineering_effort],['隐私 / 体验风险',e.privacy_risk+' / '+e.ux_risk],['处理 / 比较组退订',`${e.treatment_opt_outs}/${e.treatment_n} (${pct(e.treatment_opt_outs/e.treatment_n)}) ／ ${e.comparison_opt_outs}/${e.comparison_n} (${pct(e.comparison_opt_outs/e.comparison_n)})`],['处理 / 比较组投诉',`${e.treatment_complaints} ／ ${e.comparison_complaints}`],['现金 / 人时 / 峰值',`${c.cost} CAD ／ ${c.hours} h ／ ${c.staff} 人`],['未来预计净提升','未知（null）']].map(([k,v])=>`<tr><th>${k}</th><td>${v}</td></tr>`).join('')}</tbody></table><h3>逐项审查</h3>${c.issues.map(issueHTML).join('')}<h3>同类型活动参考</h3><p>${result.context?esc(result.context.historicalReference.rowIds.join(' · ')):'未指定活动类型'}。仅作类型参照，不是该干预的因果证据。</p><h3>证据定位</h3><p>experiments.csv → ${c.sourceId}<br>${c.evidenceRefs[0].fields.join(' · ')}</p>`);}
const columns={users:['user_id','segment','cohort_phase','first_participation_date','repeat_14d','marketing_opt_in'],campaigns:['campaign_id','title','category','new_attendees','repeat_14d_new_users','new_user_repeat_14d_rate'],contents:['content_id','content_type','related_campaign_id','impressions','ctr','exposed_repeat_14d_rate'],experiments:['experiment_id','experiment_name','study_design','treatment_n','comparison_n','observed_diff_pp']};
const labels={user_id:'用户ID',segment:'当前分群',cohort_phase:'首次参与阶段',first_participation_date:'首次参与日期',repeat_14d:'14天复参与',marketing_opt_in:'营销同意',campaign_id:'活动ID',title:'活动名称',category:'类型',new_attendees:'新到场人数',repeat_14d_new_users:'14天复参与人数',new_user_repeat_14d_rate:'14天复参与率',content_id:'内容ID',content_type:'内容类型',related_campaign_id:'相关活动',impressions:'展示次数',ctr:'点击率',exposed_repeat_14d_rate:'曝光后14天参与率',experiment_id:'实验ID',experiment_name:'实验名称',study_design:'研究设计',treatment_n:'处理组人数',comparison_n:'比较组人数',observed_diff_pp:'观察差异 pp'};
function cell(k,v){if(k.endsWith('_rate')||k==='ctr')return pct(v);if(k==='category')return categories[v];if(k==='observed_diff_pp')return pp(v);return esc(v);}
function evidence(){main.innerHTML=header('每一个判断，都能找到出处。','四张表，保留计数、分母、窗口与研究限制。','EVIDENCE LIBRARY',`<a class="button secondary" href="data/AI_Growth_Decision_Copilot_v1.zip" download>下载完整数据 ↓</a>`)+`<div class="data-controls">${Object.entries(names).map(([k,n])=>`<button class="data-tab ${table===k?'active':''}" data-table="${k}">${n} <span>${data[k].length}</span></button>`).join('')}<input class="search" id="search" aria-label="搜索数据" placeholder="搜索 ID、类型或关键词…" value="${esc(query)}"></div><div class="panel" id="data-panel"></div><div class="notice" style="margin-top:20px"><span>ⓘ</span><div>${{users:'当前CRM分群与历史首次参与cohort不同。同期入群及结果字段不能用作无偏的前置预测特征。',campaigns:'新到场与复参与人数可与users严格对账。老用户到场可能重复，不能将活动总到场数当独立人数。',contents:'内容用户是独立汇总样本；曝光后14天窗口不同于首次参与后14天。相关活动ID只是编辑关联。',experiments:'历史独立汇总样本，不与800用户硬关联。描述性区间无法消除选择偏差，也未经多重比较校正。'}[table]}</div></div>`;
 document.querySelectorAll('[data-table]').forEach(b=>b.onclick=()=>{table=b.dataset.table;page=0;query='';evidence();});$('#search').oninput=e=>{query=e.target.value;page=0;renderData();};renderData();}
function renderData(){const rows=data[table].filter(r=>Object.values(r).some(v=>String(v).toLowerCase().includes(query.toLowerCase()))),pages=Math.max(1,Math.ceil(rows.length/15));page=Math.min(page,pages-1);const cols=columns[table];$('#data-panel').innerHTML=`<div class="data-toolbar"><span>${names[table]} · ${rows.length} 条记录 · 点击详情查看全部字段</span><a href="data/${table}.csv" download>CSV ↓</a></div><div class="table-wrap"><table><thead><tr>${cols.map(k=>`<th>${labels[k]}</th>`).join('')}<th>详情</th></tr></thead><tbody>${rows.slice(page*15,page*15+15).map(r=>`<tr>${cols.map(k=>`<td>${cell(k,r[k])}</td>`).join('')}<td><button class="text-button" data-record="${esc(r[cols[0]])}" aria-label="查看 ${esc(r[cols[0]])}">↗</button></td></tr>`).join('')||`<tr><td colspan="${cols.length+1}">没有匹配记录。</td></tr>`}</tbody></table></div><div class="pagination"><span>第 ${page+1} / ${pages} 页 · 每页15条</span><div><button class="button secondary" id="prev" ${page===0?'disabled':''}>←</button><button class="button secondary" id="next" ${page>=pages-1?'disabled':''}>→</button></div></div>`;$('#prev').onclick=()=>{page--;renderData();};$('#next').onclick=()=>{page++;renderData();};document.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>recordDetail(b.dataset.record));}
function recordDetail(id){const sch=schema.tables[table],r=data[table].find(r=>r[sch.primary_key]===id);modal(`<div class="eyebrow">${table.toUpperCase()} / SOURCE ROW</div><h2>${esc(id)}</h2><table><tbody>${sch.fields.map(f=>`<tr><th>${esc(f.name)}<br><span style="font-weight:400;font-size:10px">${esc(f.description)}</span></th><td>${esc(r[f.name])}</td></tr>`).join('')}</tbody></table>`);}
function guide(){main.innerHTML=header('从候选到可解释的决策。','六步流程、一次有界复核，保留每次判断依据。','METHOD & BOUNDARIES')+`<div class="guide-grid">${[['Generation','将8个案例模板转为可检验方案；当前是规则演示，未接入大模型。'],['Diversity','按干预、人群、指标去重，按增长机制分组。'],['Reflection','检查证据、样本、偏差、资源、隐私与体验风险。'],['Ranking','默认六维权重25/20/20/15/10/10；按分差两两比较，再筛选资源可行组合。'],['Evolution','改进初排前三个方案的执行与验证细节；保留原始证据及风险。'],['Re-ranking','比较V1和V2；没有新证据或报价时不自动加分。'],['Quality Gate / Iteration','检查无可行方案、弱证据与分差过小；最多一轮复核。未解决的问题明确保留。'],['Meta-review','只归纳跨方案洞察、共性风险、关键缺口与最终选择理由；不生成新假设，不改变排序或硬性限制。'],['数据与产品边界','基于用户确认的真实业务统计构建的演示数据；CSV逐行记录由程序生成。活动与方案仅保存在当前浏览器。没有模型调用、自动执行或实验后学习。']].map(([t,d])=>`<section class="panel guide-card"><h2>${t}</h2><p>${d}</p></section>`).join('')}</div>`;}
function exportResult(){if(!result)return;modal(`<div class="eyebrow">DECISION EXPORT</div><h2>保留这次决策的依据</h2><p>${stale?'当前约束已修改，导出的是上次运行结果。请先更新组合以导出新约束。':'导出包含本次约束、历史依据、逐项审查、组合与待核实条件。'}</p><div class="head-actions"><button class="button" id="json-export">下载 JSON ↓</button><button class="button secondary" id="md-export">下载报告 ↓</button></div>`);$('#json-export').onclick=()=>{download('growth-decision-result.json',JSON.stringify(result,null,2),'application/json');toast('已导出 JSON');};$('#md-export').onclick=()=>{const r=result.ranking;const body=`# Growth Decision Copilot 决策记录\n\n模式：离线确定性规则；基于真实业务统计构建的演示数据；逐行记录为生成数据；活动信息由使用者填写；未调用外部模型。\n分析日期：${result.analysisDate}\n\n## 活动快照\n\n${JSON.stringify(result.activity,null,2)}\n\n## 输入约束\n\n\`\`\`json\n${JSON.stringify(result.config,null,2)}\n\`\`\`\n\n## 条件性推荐\n\n${r.selected.map(c=>'- '+c.name+'（'+c.sourceId+'）').join('\n')||'当前约束下无可选组合。'}\n\n历史现金占位${r.totals.cost} CAD；${r.totals.hours}人时；并行峰值保守相加${r.totals.staff}人。不是未来报价。\n\n## 逐项判断\n\n${r.decisions.map(d=>'- '+r.ordered.find(c=>c.id===d.candidateId).name+'：'+d.reason).join('\n')}\n\n## 待核实条件\n\n${r.unknown.map(s=>'- '+s).join('\n')}\n\n上线就绪：否。\n\n## 证据审查\n\n${result.reviewed.map(c=>'### '+c.name+' / '+c.sourceId+'\n\n'+c.issues.map(i=>'- '+i.title+'：'+i.detail).join('\n')).join('\n\n')}\n\n## 六步流程与质量检查\n\n${JSON.stringify({diversity:result.diversity.groups,evolved:result.evolved,qualityGate:result.qualityGate,metaReview:result.metaReview,iteration:result.iteration,versionComparison:result.versionComparison},null,2)}\n\n## 口径\n\n36/200=18%；186/600=31%；相对差异72.22%，非因果估计。当前14天窗口内人数0，未来实验需新招募。${r.method}\n`;download('growth-decision-report.md',body,'text/markdown;charset=utf-8');toast('已导出报告');};}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();window.scrollTo({top:0});});
$('.brand').onclick=e=>{e.preventDefault();view='overview';render();};
$('.close-editor').onclick=()=>$('#editor').close();
$('#editor-cancel').onclick=()=>$('#editor').close();
try{schema=await get('data/schema.json');data=Object.fromEntries(await Promise.all(Object.keys(schema.tables).map(async k=>[k,coerce(parseCSV(await get(`data/${k}.csv`,'text')),schema.tables[k])])));summary=summarize(data);initializeWorkspace();render();}catch(e){main.innerHTML=`<div class="notice"><strong>数据读取失败</strong><span>${esc(e.message)}。请刷新重试。</span></div>`;}
